private readonly TallyPrivateCompanySessionService _privateSessions = TallyPrivateCompanySessionService.Shared;
private int _autoSessionScheduled;
private DateTime _lastAutomaticSessionAttemptUtc = DateTime.MinValue;

/// <summary>
/// R24: opt-in, one-client unattended Auto Tally Import cycle. It deliberately uses
/// the EXISTING RefreshNowAsync(forceLinkedSynchronization) / FY Master+Voucher
/// baseline and its duplicate/ALTERID protections; no parallel importer exists.
/// Background folder watchers remain independent of this cycle.
/// </summary>
private void MaybeScheduleAutomaticTallySession()
{
    if (_disposed || !_automationService.IsInitialLocalPreparationComplete ||
        !_automationService.IsLocalPreparationComplete || !IsInitialLocalPreparationReady() ||
        _automationService.IsPaused) return;
    var client = _clientContext.CurrentClient;
    if (client is null || client.IsArchived) return;
    var link = _repository.GetLinkForClient(client.Id);
    if (link is null || !AutoTallyImportPreference.IsEnabled(_clientPreferenceRepository, client) ||
        !AutoTallyImportPreference.AutoOpen(_clientPreferenceRepository, client)) return;
    // Tally's ordinary 5-second loop stays intact while open. With Auto Close on,
    // an unattended new session is permitted only once per 15-minute interval.
    if (DateTime.UtcNow - _lastAutomaticSessionAttemptUtc < TimeSpan.FromMinutes(15) ||
        TallyPrivateCompanySessionService.AnyTallyRunning()) return;
    if (Interlocked.CompareExchange(ref _autoSessionScheduled, 1, 0) != 0) return;
    _lastAutomaticSessionAttemptUtc = DateTime.UtcNow;
    _ = RunAutomaticTallySessionAsync(client, link);
}

private async Task RunAutomaticTallySessionAsync(ClientProfile client, TallyClientLink link)
{
    try
    {
        // Avoid stealing another client/FY's active coordinator or Tally process.
        if (_disposed || _clientContext.CurrentClient is not { } active ||
            active.Id != client.Id || active.FinancialYear != client.FinancialYear ||
            !_automationService.IsLocalPreparationComplete) return;
        var exe = _applicationLaunchService.LocateTallyExecutableForIcon(client.Id);
        if (string.IsNullOrWhiteSpace(exe)) return;
        var start = await _privateSessions.StartAsync(client, link, exe, automatic: true);
        if (!start.Success)
        {
            AutomationDiagnosticLog.Write("TALLY-AUTO-OPEN", start.Message, client.ClientCode);
            return;
        }
        ConnectionStatus = "Tally Auto Open • waiting for verified company";
        // The same coordinator's normal XML discovery is the authority for loaded
        // companies. Never consider a successful Process.Start to be a sync success.
        var deadline = DateTime.UtcNow.AddSeconds(80);
        TallyCompanyInfo? target = null;
        while (!_disposed && DateTime.UtcNow < deadline)
        {
            if (!_privateSessions.OwnsAutomaticSession(client) ||
                _clientContext.CurrentClient is not { } current || current.Id != client.Id ||
                current.FinancialYear != client.FinancialYear) return;
            await Task.Delay(1500);
            if (!await _httpService.ProbeEndpointAsync(TimeSpan.FromMilliseconds(750))) continue;
            var found = await _httpService.DiscoverCompaniesAsync(includeLightweightCounts: false);
            target = found.Count == 1 ? found.SingleOrDefault(company =>
                company.CompanyKey.Equals(link.CompanyKey, StringComparison.OrdinalIgnoreCase) &&
                company.Name.Equals(link.CompanyName, StringComparison.OrdinalIgnoreCase)) : null;
            if (target is not null) break;
        }
        if (target is null)
        {
            AutomationDiagnosticLog.Write("TALLY-AUTO-OPEN", "Loaded company identity could not be verified; left Tally open for review.", client.ClientCode);
            return;
        }

        // Do not call force Refresh in a busy coordinator; it would turn an intended
        // existing import/export into a competing heavy Tally request.
        if (_httpService.IsImportInProgress || _httpService.IsExportInProgress) return;
        await RefreshNowAsync(forceLinkedSynchronization: true);
        var state = _repository.GetBankSyncState(client.Id, client.FinancialYear, target.CompanyKey);
        var synced = state is not null && state.LastFullSyncUtc >= _lastAutomaticSessionAttemptUtc &&
                     HasCompleteActiveFyVoucherAuthority(client, target, state);
        if (!synced)
        {
            AutomationDiagnosticLog.Write("TALLY-AUTO-CLOSE", "Authority checkpoint incomplete. Left AAH-started Tally open for the normal heartbeat to retry.", client.ClientCode);
            return;
        }
        // Auto Close is independent and OFF by default. Let the existing file watcher,
        // sync gates, and cache consumers finish; no forced process kill is allowed.
        if (!AutoTallyImportPreference.AutoClose(_clientPreferenceRepository, client)) return;
        // Auto Import can continue consuming queued local files after the Tally authority
        // read finishes. Retry graceful auto-close once idle instead of giving up after
        // just eight seconds. Never close if user switches Client/FY or loads other data.
        var closeDeadline = DateTime.UtcNow.AddHours(1);
        while (!_disposed && DateTime.UtcNow < closeDeadline && _privateSessions.OwnsAutomaticSession(client))
        {
            await Task.Delay(TimeSpan.FromSeconds(8));
            if (_clientContext.CurrentClient is not { } closingClient ||
                closingClient.Id != client.Id || closingClient.FinancialYear != client.FinancialYear) return;
            if (_backgroundTallySyncScheduled != 0 || _httpService.IsImportInProgress ||
                _httpService.IsExportInProgress || !_automationService.IsLocalPreparationComplete) continue;
            var open = await _httpService.DiscoverCompaniesAsync(includeLightweightCounts: false);
            var onlyOwn = open.Count == 1 && open[0].CompanyKey.Equals(link.CompanyKey, StringComparison.OrdinalIgnoreCase);
            if (!onlyOwn) return; // user may have loaded another company
            if (_privateSessions.TryCloseAutomaticSession(client, synced,
                _automationService.IsLocalPreparationComplete, onlyOwn)) return;
            // AAH-owned process may refuse the graceful close (dialog); do not retry
            // a forced close or kill it. Leave that window for the user.
            return;
        }
        AutomationDiagnosticLog.Write("TALLY-AUTO-CLOSE", "Auto-close safety wait ended without a quiet queue; Tally left open, no process killed.", client.ClientCode);
    }
    catch (Exception ex)
    {
        AutomationDiagnosticLog.Write("TALLY-AUTO-SESSION", "Unattended cycle deferred; user Tally remains untouched: " + ex.Message, client.ClientCode);
    }
    finally
    {
        Interlocked.Exchange(ref _autoSessionScheduled, 0);
    }
}

// Only one exact-company session per cooldown, after the established local
// preparation phase. Never try while another Tally process is already running.
MaybeScheduleAutomaticTallySession();

